/* The bootstrapper's windows: the launch (progress) window, the update
 * prompt, and the launcher/settings window. One compilation unit made of
 * the files in ui/, so every build command stays a single gcc call:
 *   ui/style.h         the look (CSS)
 *   ui/icons.h         our icons, generated by make-ui-icons.py
 *   ui/common.c        helpers, icons, window chrome, card builders
 *   ui/test-channel.c  the test-only control channel
 *   ui/progress.c      the launch window and the shared cancel protocol
 *   ui/prompt.c        the update prompt
 *   ui/launcher.c      the launcher and settings window */

/* lstat(2), O_NOFOLLOW and O_CLOEXEC are exposed by _GNU_SOURCE; the UI build
 * compiles with -std=c11, which otherwise hides them. */
#define _GNU_SOURCE

#include <gtk/gtk.h>
#include <json-glib/json-glib.h>
#include <gio/gio.h>
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/file.h>
#include <sys/stat.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define UI_DELAY_MS 450
#define CANCEL_POLL_MS 250

#include "ui/style.h"
#include "ui/icons.h"
#include "ui/common.c"
#include "ui/test-channel.c"

/* Every window mode starts here: GTK, the shared style, the test channel. */
static gboolean ui_init(void) {
    if (!gtk_init_check(NULL, NULL)) return FALSE;
    apply_css(); ui_test_init();
    return TRUE;
}

#include "ui/progress.c"
#include "ui/prompt.c"
#include "ui/launcher.c"

int main(int argc, char **argv) {
    g_set_prgname("roblox-mac-port");
    g_set_application_name("Roblox");
    if (argc >= 2 && !strcmp(argv[1], "--progress")) return run_progress(argc >= 3 ? argv[2] : ".");
    if (argc >= 4 && !strcmp(argv[1], "--dialog")) return run_dialog(argv[2], argv[3], argc >= 6 ? argv[4] : "", argc >= 6 ? argv[5] : "");
    if (argc >= 3 && !strcmp(argv[1], "--settings")) return run_launcher(argv[2], TRUE);
    if (argc >= 3 && !strcmp(argv[1], "--launcher")) return run_launcher(argv[2], FALSE);
    return 2;
}
